private void assertHelpOutputEquals(String expected, String actual) {
    // Split on any line‑break sequence (\r, \n, or \r\n) to avoid platform‑specific failures.
    String[] expectedLines = expected.split("\\R");
    String[] actualLines   = actual.split("\\R");
    assertArrayEquals(expectedLines, actualLines,
        () -> "Help output differed.\nExpected:\n" + expected + "\nActual:\n" + actual);
}

