/**
 * Helper that compares multi‑line strings line‑by‑line.
 * This avoids the {@code SensitiveEquality} smell of asserting a large
 * string in a single {@code assertEquals} call.
 *
 * @param expected the expected multi‑line string
 * @param actual   the actual multi‑line string produced by the code under test
 * @param message  description used when an assertion fails
 */
private static void assertWrappedTextEquals(final String expected,
                                            final String actual,
                                            final String message) {
    // Split on any line‑separator (\\R) and keep trailing empty lines if any.
    final String[] expectedLines = expected.split("\\R", -1);
    final String[] actualLines   = actual.split("\\R", -1);
    assertArrayEquals(expectedLines, actualLines, message);
}

