/**
 * Helper that parses the supplied arguments using the shared {@code parser}
 * and {@code options}. If parsing throws any exception, the test fails
 * immediately.
 *
 * @param args command line arguments to parse
 * @return the resulting {@link CommandLine}
 */
private CommandLine parseOrFail(String[] args) {
    try {
        return parser.parse(options, args);
    } catch (Exception e) {
        fail("Unexpected exception while parsing arguments: " + e.getMessage());
        // The following return is unreachable because fail() throws an AssertionError,
        // but it satisfies the compiler.
        return null;
    }
}

