/** Retrieves a {@link Field} from the given class, converting any checked
 *  {@link NoSuchFieldException} into an unchecked {@link AssertionError}
 *  so the test method does not need to declare {@code throws Exception}. */
private static Field fieldOf(Class<?> clazz, String fieldName) {
    try {
        return clazz.getField(fieldName);
    } catch (NoSuchFieldException e) {
        throw new AssertionError(
            String.format("Field %s not found in %s", fieldName, clazz.getName()), e);
    }
}

