/**
 * Executes {@link #serializedCopy(Object)} and converts any checked exceptions
 * into an {@link AssertionError}. This keeps the test signature clean and
 * removes the need for a {@code throws} clause.
 */
@SuppressWarnings("unchecked") // Serialization promises to return the same type.
private static <T> T serializedCopyUnchecked(T object) {
    try {
        return serializedCopy(object);
    } catch (IOException | ClassNotFoundException e) {
        throw new AssertionError("Failed to serialize/deserialize object", e);
    }
}

