private static final String PREFIX = ")]}'\n";

/** Helper that builds a {@link JsonWriter} with the same configuration as the original test. */
private static JsonWriter createLenientPrettyWriter(StringWriter out) {
  return new GsonBuilder()
      .disableHtmlEscaping()
      .generateNonExecutableJson()
      .setPrettyPrinting()
      .serializeNulls()
      .setLenient()                // deprecated, kept for parity with original test
      .create()
      .newJsonWriter(out);
}

/** Writes the same JSON structure as the original test and returns the full output. */
private static String writeJsonAndReturnOutput() throws IOException {
  StringWriter writer = new StringWriter();
  JsonWriter jsonWriter = createLenientPrettyWriter(writer);

  jsonWriter.beginObject();
  jsonWriter.name("test");
  jsonWriter.nullValue();
  jsonWriter.name("<test2");
  jsonWriter.value(true);
  jsonWriter.endObject();

  // Additional top‑level value (outside the object)
  jsonWriter.value(1);
  jsonWriter.close();

  return writer.toString();
}

@Test
public void testNewJsonWriter_Custom_objectStructure() throws IOException {
  String output = writeJsonAndReturnOutput();

  // Verify the non‑JSON prefix that Gson adds when {@code generateNonExecutableJson()} is used.
  assertThat(output).startsWith(PREFIX);

  // Extract the JSON object part (everything between the prefix and the trailing "1").
  String withoutPrefix = output.substring(PREFIX.length());
  int closingBraceIdx = withoutPrefix.lastIndexOf('}');
  assertThat(closingBraceIdx).isGreaterThan(-1); // sanity check

  String jsonObjectText = withoutPrefix.substring(0, closingBraceIdx + 1);
  JsonElement parsed = JsonParser.parseString(jsonObjectText);
  assertThat(parsed.isJsonObject()).isTrue();

  JsonObject obj = parsed.getAsJsonObject();
  // Expected members:
  //   "test": null
  //   "<test2": true
  assertThat(obj.has("test")).isTrue();
  assertThat(obj.get("test").isJsonNull()).isTrue();

  assertThat(obj.has("<test2")).isTrue();
  assertThat(obj.get("<test2").isJsonPrimitive()).isTrue();
  assertThat(obj.get("<test2").getAsBoolean()).isTrue();
}

@Test
public void testNewJsonWriter_Custom_additionalTopLevelValue() throws IOException {
  String output = writeJsonAndReturnOutput();

  // Verify the non‑JSON prefix.
  assertThat(output).startsWith(PREFIX);

  // After the prefix and the JSON object, the only remaining characters should be the top‑level
  // value written by the original test ("1").
  String afterPrefix = output.substring(PREFIX.length());
  int closingBraceIdx = afterPrefix.lastIndexOf('}');
  assertThat(closingBraceIdx).isGreaterThan(-1); // sanity check

  String trailing = afterPrefix.substring(closingBraceIdx + 1);
  assertThat(trailing).isEqualTo("1");
}

