private static List<Double> writeAndRead(double value) throws IOException {
  StringWriter sw = new StringWriter();
  JsonWriter writer = new JsonWriter(sw);
  writer.setStrictness(Strictness.LENIENT);
  writer.beginArray();
  writer.value(value);
  writer.endArray();
  writer.flush();

  JsonReader reader = new JsonReader(new StringReader(sw.toString()));
  reader.setLenient(true);
  reader.beginArray();
  double read = reader.nextDouble();
  reader.endArray();
  return List.of(read);
}

