/** Helper that creates a {@link JsonReader} for the given JSON literal. */
private static JsonReader newJsonReader(String json) {
  return new JsonReader(new StringReader(json));
}

/** Reads {@code count} booleans from {@code reader} and returns them as a list. */
private static List<Boolean> readBooleans(JsonReader reader, int count) throws IOException {
  List<Boolean> result = new ArrayList<>(count);
  for (int i = 0; i < count; i++) {
    result.add(reader.nextBoolean());
  }
  return result;
}

/** Reads two consecutive {@code null} literals from {@code reader}. */
private static void readTwoNulls(JsonReader reader) throws IOException {
  reader.nextNull();
  reader.nextNull();
}

@Test
public void testMixedCaseLiterals_values() throws IOException {
  JsonReader reader = newJsonReader("[True,TruE,False,FALSE,NULL,nulL]");
  reader.beginArray();

  // Verify the sequence of boolean literals (case‑insensitive).
  List<Boolean> booleans = readBooleans(reader, 4);
  assertThat(booleans).containsExactly(true, true, false, false).inOrder();

  // Verify the two null literals.
  readTwoNulls(reader);
  assertThat(reader.peek()).isEqualTo(NULL);

  // Consume the end of the array so the reader is positioned after the array.
  reader.endArray();
}

@Test
public void testMixedCaseLiterals_endOfDocument() throws IOException {
  JsonReader reader = newJsonReader("[True,TruE,False,FALSE,NULL,nulL]");
  reader.beginArray();

  // Exhaust the array (four booleans + two nulls) to reach the end.
  readBooleans(reader, 4);
  readTwoNulls(reader);
  reader.endArray();

  // After the array is closed the next token must be END_DOCUMENT.
  assertThat(reader.peek()).isEqualTo(END_DOCUMENT);
}

