/** Returns the JSON text currently written by the given {@link JsonWriter}. */
private static String getWrittenJson(JsonWriter writer) {
  // The underlying StringWriter is not exposed, so we re‑create it via reflection only
  // for testing purposes. Since JsonWriter does not expose its writer, we rely on the
  // fact that the writer we passed in is a StringWriter.
  // In production code this helper would not be needed.
  try {
    java.lang.reflect.Field outField = JsonWriter.class.getDeclaredField("out");
    outField.setAccessible(true);
    StringWriter sw = (StringWriter) outField.get(writer);
    return sw.toString();
  } catch (ReflectiveOperationException e) {
    throw new AssertionError("Unable to retrieve written JSON", e);
  }
}

