private static final String HTML = """
    <form>
        <input name='one' value='two'>
        <select name='three'>
            <option value='not'></option>
            <option value='four' selected></option>
            <option value='five' selected></option>
        </select>
        <textarea name='six'>seven</textarea>
        <input name='seven' type='radio' value='on' checked>
        <input name='seven' type='radio' value='off'>
        <input name='eight' type='checkbox' checked>
        <input name='nine' type='checkbox' value='unset'>
        <input name='ten' value='text' disabled>
        <input name='eleven' value='text' type='button'>
    </form>
    """;

private static final int EXPECTED_DATA_SIZE = 6;

private static final String[][] EXPECTED_KEY_VALUES = {
        {"one", "two"},
        {"three", "four"},
        {"three", "five"},
        {"six", "seven"},
        {"seven", "on"},
        {"eight", "on"}
};

private static final String[] EXCLUDED_KEYS = {"nine", "ten", "eleven"};

private List<Connection.KeyVal> parseFormData() {
    Document doc = Jsoup.parse(HTML);
    FormElement form = (FormElement) doc.select("form").first();
    return form.formData();
}

private void assertKeyValue(Connection.KeyVal kv, String expectedKey, String expectedValue) {
    assertEquals("Unexpected key", expectedKey, kv.key());
    assertEquals("Unexpected value for key '" + expectedKey + "'", expectedValue, kv.value());
}

@Test
public void createsFormData_size() {
    List<Connection.KeyVal> data = parseFormData();
    assertEquals("Form data size mismatch", EXPECTED_DATA_SIZE, data.size());
}

@Test
public void createsFormData_keyValues() {
    List<Connection.KeyVal> data = parseFormData();
    for (int i = 0; i < EXPECTED_KEY_VALUES.length; i++) {
        Connection.KeyVal kv = data.get(i);
        String expectedKey = EXPECTED_KEY_VALUES[i][0];
        String expectedValue = EXPECTED_KEY_VALUES[i][1];
        assertKeyValue(kv, expectedKey, expectedValue);
    }
}

@Test
public void createsFormData_exclusions() {
    List<Connection.KeyVal> data = parseFormData();
    for (String excludedKey : EXCLUDED_KEYS) {
        boolean present = data.stream().anyMatch(kv -> kv.key().equals(excludedKey));
        assertFalse("Key '" + excludedKey + "' should not be present in form data", present);
    }
}

