private static final String ORIGINAL_HTML = "<p>One <span>Two</span> Three <br> Four</p>";
private static final String EXPECTED_FULL_TEXT = "One Two three-more Fo-ur";
private static final String EXPECTED_OWN_TEXT = "One three-more Fo-ur";
private static final int EXPECTED_TEXT_NODE_COUNT = 4;

// --- Helper to prepare the element under test ---
private Element manipulateParagraph() {
    Document doc = Jsoup.parse(ORIGINAL_HTML);
    Element p = doc.select("p").first();

    List<TextNode> textNodes = p.textNodes();
    // modify the second text node
    textNodes.get(1).text(" three-more ");
    // split the third text node and modify the new node
    textNodes.get(2).splitText(3).text("-ur");

    return p;
}

@Test
public void testManipulateTextNodes_fullText() {
    Element p = manipulateParagraph();
    assertEquals("Full text after manipulation", EXPECTED_FULL_TEXT, p.text());
}

@Test
public void testManipulateTextNodes_ownText() {
    Element p = manipulateParagraph();
    assertEquals("Own text after manipulation", EXPECTED_OWN_TEXT, p.ownText());
}

@Test
public void testManipulateTextNodes_textNodeCount() {
    Element p = manipulateParagraph();
    assertEquals("Number of text nodes after split", EXPECTED_TEXT_NODE_COUNT, p.textNodes().size());
}

