@Test
public void testIteratorSkipsInternal() {
    Attributes a = new Attributes();
    a.put("One", "One");
    a.put(Attributes.internalKey("baseUri"), "example.com");
    a.put("Two", "Two");
    a.put(Attributes.internalKey("another"), "example.com");

    Iterator<Attribute> it = a.iterator();
    assertTrue(it.hasNext());
    assertEquals("One", it.next().getKey());
    assertTrue(it.hasNext());
    assertEquals("Two", it.next().getKey());
    assertFalse(it.hasNext());

    int seen = 0;
    for (Attribute attribute : a) {
        seen++;
    }
    assertEquals(2, seen);
}

proposals.refactored:
private static final int EXPECTED_VISIBLE_ATTRIBUTES = 2;
private static final String KEY_ONE = "One";
private static final String KEY_TWO = "Two";

private Attributes createAttributesWithInternals() {
    Attributes a = new Attributes();
    a.put(KEY_ONE, KEY_ONE);
    a.put(Attributes.internalKey("baseUri"), "example.com");
    a.put(KEY_TWO, KEY_TWO);
    a.put(Attributes.internalKey("another"), "example.com");
    return a;
}

@Test
public void testIteratorSkipsInternal_iteratesInOrder() {
    Attributes a = createAttributesWithInternals();
    Iterator<Attribute> it = a.iterator();

    assertTrue("Iterator should have first element", it.hasNext());
    assertEquals("First visible attribute key mismatch", KEY_ONE, it.next().getKey());

    assertTrue("Iterator should have second element", it.hasNext());
    assertEquals("Second visible attribute key mismatch", KEY_TWO, it.next().getKey());

    assertFalse("Iterator should be exhausted after two visible attributes", it.hasNext());
}

@Test
public void testIteratorSkipsInternal_countsVisibleAttributes() {
    Attributes a = createAttributesWithInternals();
    int seen = 0;
    for (Attribute attribute : a) {
        seen++;
    }
    assertEquals("Number of visible attributes should match expected", EXPECTED_VISIBLE_ATTRIBUTES, seen);
}

