private static final String HTML_WITH_SPAN = "<div><span class=' mellow yellow '>Hello <b>Yellow</b></span></div>";
private static final String EXPECTED_SPAN_CLASS_NAME = "mellow yellow";
private static final Set<String> EXPECTED_SPAN_CLASSES = Set.of("mellow", "yellow");
private static final String EXPECTED_DOC_CLASS_NAME = "";
private static final Set<String> EMPTY_CLASS_SET = Set.of();

@Test
public void testClassDomMethods_spanClassAttributes() {
    Document doc = Jsoup.parse(HTML_WITH_SPAN);
    Element span = doc.getElementsByAttribute("class").first();

    assertEquals("Span class attribute value", EXPECTED_SPAN_CLASS_NAME, span.className());
    assertTrue("Span should have class 'mellow'", span.hasClass("mellow"));
    assertTrue("Span should have class 'yellow'", span.hasClass("yellow"));

    Set<String> actualClasses = span.classNames();
    assertEquals("Number of classes on span", EXPECTED_SPAN_CLASSES.size(), actualClasses.size());
    for (String cls : EXPECTED_SPAN_CLASSES) {
        assertTrue("Span class set should contain '" + cls + "'", actualClasses.contains(cls));
    }
}

@Test
public void testClassDomMethods_documentClassAttributes() {
    Document doc = Jsoup.parse(HTML_WITH_SPAN);
    assertEquals("Document class attribute should be empty", EXPECTED_DOC_CLASS_NAME, doc.className());

    Set<String> docClasses = doc.classNames();
    assertEquals("Document should have no classes", EMPTY_CLASS_SET.size(), docClasses.size());
    assertFalse("Document must not have class 'mellow'", doc.hasClass("mellow"));
}

