@Test
public void testHasTextWhenIterating_allTextNodesAreNonBlank() {
    Document doc = Jsoup.parse("<div>One <p>Two <p>Three");
    List<TextNode> textNodes = collectTextNodes(doc);

    // each TextNode must contain non‑blank text
    for (TextNode tn : textNodes) {
        assertFalse("TextNode should not be blank: '" + tn.text() + "'",
                    StringUtil.isBlank(tn.text()));
    }

    // at least one TextNode must have been found
    assertFalse("Expected at least one TextNode", textNodes.isEmpty());
}

@Test
public void testHasTextWhenIterating_firstTextNodeHasExpectedContent() {
    Document doc = Jsoup.parse("<div>One <p>Two <p>Three");
    List<TextNode> textNodes = collectTextNodes(doc);

    // pre‑condition: there is at least one TextNode
    assertFalse("Expected at least one TextNode", textNodes.isEmpty());

    TextNode first = textNodes.get(0);
    assertEquals("One ", first.text());
    assertEquals("One ", first.getWholeText());
}

/**
 * Helper that extracts every {@link TextNode} from the given document.
 */
private List<TextNode> collectTextNodes(Document doc) {
    List<TextNode> result = new ArrayList<>();
    for (Element el : doc.getAllElements()) {
        for (Node node : el.childNodes()) {
            if (node instanceof TextNode) {
                result.add((TextNode) node);
            }
        }
    }
    return result;
}

